package dev.hackuniversity.roombook.bookings;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Instant;

import org.junit.jupiter.api.Test;

class OnHalfHourTest {

    @Test
    void acceptsTheHourAndTheHalfHour() {
        // Arrange: two times on the boundary.
        Instant onTheHour = Instant.parse("2026-10-05T14:00:00Z");
        Instant halfPast = Instant.parse("2026-10-05T14:30:00Z");

        // Act and assert: call the method and check what it returns.
        assertThat(BookingService.onHalfHour(onTheHour)).isTrue();
        assertThat(BookingService.onHalfHour(halfPast)).isTrue();
    }

    @Test
    void rejectsAnythingInBetween() {
        assertThat(BookingService.onHalfHour(Instant.parse("2026-10-05T14:10:00Z"))).isFalse();
    }
}

package dev.hackuniversity.roombook.bookings;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.catchThrowableOfType;

import java.time.Instant;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import dev.hackuniversity.roombook.common.ConflictException;
import dev.hackuniversity.roombook.common.FieldViolation;
import dev.hackuniversity.roombook.common.UnprocessableException;
import dev.hackuniversity.roombook.rooms.InMemoryRoomRepository;
import dev.hackuniversity.roombook.support.TestBeans;

class BookingServiceTest {

    static final long ADA = 1;

    InMemoryBookingRepository bookings;
    BookingService service;

    @BeforeEach
    void setUp() {
        bookings = new InMemoryBookingRepository(TestBeans.NOW);
        service = new BookingService(bookings, new InMemoryRoomRepository(TestBeans.ROOMS), TestBeans.NOW);
    }

    static NewBooking booking(String startsAt, String endsAt, int attendees) {
        return new NewBooking(1, ADA, Instant.parse(startsAt), Instant.parse(endsAt), attendees, null);
    }

    @Test
    void savesAValidBookingForTheCaller() {
        Booking booking = service.create(booking("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z", 3));

        assertThat(booking.id()).isEqualTo(1001);
        assertThat(booking.userId()).isEqualTo(ADA);
        assertThat(booking.createdAt()).isEqualTo(Instant.parse("2026-10-01T09:00:00Z"));
        assertThat(bookings.findById(1001)).contains(booking);
    }

    @ParameterizedTest(name = "rejects a booking that {0}")
    @CsvSource({
        "starts off the half hour,   2026-10-05T14:10:00Z, 2026-10-05T15:30:00Z, 3, startsAt",
        "lasts under 30 minutes,     2026-10-05T14:00:00Z, 2026-10-05T14:00:00Z, 3, endsAt",
        "lasts over 3 hours,         2026-10-05T14:00:00Z, 2026-10-05T17:30:00Z, 3, endsAt",
        "starts in the past,         2026-09-30T14:00:00Z, 2026-09-30T15:00:00Z, 3, startsAt",
        "starts over 14 days ahead,  2026-10-16T14:00:00Z, 2026-10-16T15:00:00Z, 3, startsAt",
        "has more people than seats, 2026-10-05T14:00:00Z, 2026-10-05T15:30:00Z, 7, attendees",
    })
    void rejectsABookingThatBreaksARule(String why, String startsAt, String endsAt, int attendees, String field) {
        UnprocessableException e = catchThrowableOfType(UnprocessableException.class,
                () -> service.create(booking(startsAt, endsAt, attendees)));

        assertThat(e.violations()).extracting(FieldViolation::field).contains(field);
        assertThat(bookings.countUpcoming(ADA, TestBeans.NOW.instant())).isZero();
    }

    @Test
    void refusesAFourthUpcomingBooking() {
        for (String day : new String[] {"05", "06", "07"}) {
            service.create(booking("2026-10-" + day + "T14:00:00Z", "2026-10-" + day + "T15:00:00Z", 3));
        }

        assertThatThrownBy(() -> service.create(booking("2026-10-08T14:00:00Z", "2026-10-08T15:00:00Z", 3)))
                .isInstanceOf(ConflictException.class);
    }
}

