package dev.hackuniversity.roombook.support;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.List;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;

import dev.hackuniversity.roombook.bookings.InMemoryBookingRepository;
import dev.hackuniversity.roombook.rooms.InMemoryRoomRepository;
import dev.hackuniversity.roombook.rooms.Room;

/** In-memory repositories and a fixed clock, in place of the real ones. */
@TestConfiguration
public class TestBeans {

    public static final List<Room> ROOMS = List.of(
            new Room(1, "Turing", "main-library", 6, List.of("whiteboard", "screen")),
            new Room(2, "Lovelace", "main-library", 4, List.of("whiteboard")));

    public static final Clock NOW = Clock.fixed(Instant.parse("2026-10-01T09:00:00Z"), ZoneOffset.UTC);

    @Bean
    Clock clock() {
        return NOW;
    }

    @Bean
    InMemoryRoomRepository rooms() {
        return new InMemoryRoomRepository(ROOMS);
    }

    @Bean
    InMemoryBookingRepository bookings() {
        return new InMemoryBookingRepository(NOW);
    }
}

package dev.hackuniversity.roombook.bookings;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.authentication;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;

@WebMvcTest(BookingController.class)
@Import({BookingService.class, SecurityConfig.class, ProblemWriter.class, TestBeans.class})
class BookingControllerTest {

    static final String BOOKING = """
            {"roomId": 1, "startsAt": "2026-10-05T14:00:00Z", "endsAt": "2026-10-05T15:30:00Z", "attendees": 3}""";

    /** Ada, signed in: the principal her session would hold, and the CSRF token her browser sends. */
    static final RequestPostProcessor ADA = signedIn(Roles.user("session", 1L, "member", null, null));

    /** A browser with a CSRF token and no session: nobody is signed in. */
    static final RequestPostProcessor NOBODY = csrf();

    static RequestPostProcessor signedIn(RoombookPrincipal caller) {
        RequestPostProcessor session = authentication(new RoombookAuthentication(caller));
        return request -> csrf().postProcessRequest(session.postProcessRequest(request));
    }

    // The security config needs these two, and no test here sends an API key or a password.
    @MockitoBean ApiKeys apiKeys;
    @MockitoBean RoombookUserDetailsService users;

    @Autowired MockMvcTester mvc;
    @Autowired InMemoryBookingRepository bookings;

    /** Spring keeps one context, and so one fake, for every test class that shares it: empty it first. */
    @BeforeEach
    void emptyTheFake() {
        bookings.clear();
    }

    MvcTestResult post(String body, RequestPostProcessor caller) {
        return mvc.post().uri("/v1/bookings").with(caller).contentType(MediaType.APPLICATION_JSON).content(body).exchange();
    }

    @Test
    void createsTheBookingAndSaysWhereItLives() {
        MvcTestResult res = post(BOOKING, ADA);

        assertThat(res).hasStatus(HttpStatus.CREATED).hasHeader("Location", "/v1/bookings/1001");
        assertThat(res).bodyJson().extractingPath("$.userId").isEqualTo(1);
        assertThat(res).bodyJson().extractingPath("$.status").isEqualTo("confirmed");
        assertThat(res).bodyJson().extractingPath("$.startsAt").isEqualTo("2026-10-05T14:00:00Z");
    }

    @Test
    void answers401AndAProblemWhenNobodyIsSignedIn() {
        MvcTestResult res = post(BOOKING, NOBODY);

        assertThat(res).hasStatus(HttpStatus.UNAUTHORIZED).hasHeader("WWW-Authenticate", "Bearer realm=\"roombook\"");
        assertThat(res).hasContentType(MediaType.APPLICATION_PROBLEM_JSON);
        assertThat(res).bodyJson().extractingPath("$.type").isEqualTo("https://roombook.example/problems/unauthorized");
    }

    @Test
    void reportsEveryInvalidFieldAtOnce() {
        MvcTestResult res = post(BOOKING.replace("14:00:00Z", "14:10:00Z").replace("\"attendees\": 3", "\"attendees\": 9"), ADA);

        assertThat(res).hasStatus(HttpStatus.UNPROCESSABLE_CONTENT);
        assertThat(res).bodyJson().isLenientlyEqualTo("""
                {"errors": [
                  {"field": "startsAt", "message": "must be on the hour or half past"},
                  {"field": "attendees", "message": "Turing holds at most 6 people"}
                ]}""");
    }

    // ...the 409 and 400 tests follow the same pattern
}

package dev.hackuniversity.roombook.bookings;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Instant;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.jdbc.test.autoconfigure.AutoConfigureTestDatabase;
import org.springframework.boot.jdbc.test.autoconfigure.JdbcTest;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.context.jdbc.Sql;

import dev.hackuniversity.roombook.common.ConflictException;

@JdbcTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@TestPropertySource(properties = "spring.datasource.url=${TEST_DATABASE_URL}")
@EnabledIfEnvironmentVariable(named = "TEST_DATABASE_URL", matches = ".*_test(\\?.*)?")
@Import(JdbcBookingRepository.class)
@Sql({"/fixtures/reset.sql", "/fixtures/seed.sql"})
class JdbcBookingRepositoryIT {

    @Autowired
    BookingRepository bookings;

    static NewBooking at(String start, String end) {
        return new NewBooking(1, 1, Instant.parse(start), Instant.parse(end), 3, null);
    }

    @Test
    void savesABookingAndReadsItBack() {
        Booking saved = bookings.insert(at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z"));

        assertThat(saved.id()).isEqualTo(1001);
        assertThat(saved.status()).isEqualTo(BookingStatus.CONFIRMED);
        assertThat(bookings.findById(saved.id())).contains(saved);
    }

    @Test
    void turnsTheExclusionConstraintIntoAConflict() {
        bookings.insert(at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z"));

        assertThatThrownBy(() -> bookings.insert(at("2026-10-05T15:00:00Z", "2026-10-05T16:00:00Z")))
                .isInstanceOf(ConflictException.class);
    }

    @Test
    void allowsABookingThatStartsWhenTheLastOneEnds() {
        bookings.insert(at("2026-10-05T14:00:00Z", "2026-10-05T15:30:00Z"));

        assertThat(bookings.insert(at("2026-10-05T15:30:00Z", "2026-10-05T16:00:00Z"))).isNotNull();
    }
}

package dev.hackuniversity.roombook;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.DayOfWeek;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.time.temporal.TemporalAdjusters;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.resttestclient.autoconfigure.AutoConfigureRestTestClient;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.context.jdbc.Sql;
import org.springframework.test.web.servlet.client.RestTestClient;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@AutoConfigureRestTestClient
@TestPropertySource(properties = "spring.datasource.url=${TEST_DATABASE_URL}")
@EnabledIfEnvironmentVariable(named = "TEST_DATABASE_URL", matches = ".*_test(\\?.*)?")
@Sql({"/fixtures/reset.sql", "/fixtures/seed.sql"})
class BookingFlowIT {

    /** Next Monday at 14:00 UTC, worked out from today: always in the future, never over 14 days ahead. */
    static final Instant MONDAY = LocalDate.now(ZoneOffset.UTC).with(TemporalAdjusters.next(DayOfWeek.MONDAY))
            .atTime(14, 0).toInstant(ZoneOffset.UTC);

    static final Map<String, Object> BOOKING = Map.of(
            "roomId", 1, "startsAt", MONDAY.toString(), "endsAt", MONDAY.plus(Duration.ofMinutes(90)).toString(), "attendees", 3);

    @Autowired
    RestTestClient http;

    String signIn() {
        Map<?, ?> token = http.post().uri("/v1/auth/token")
                .body(Map.of("email", "ada@roombook.example", "password", "correct horse battery staple"))
                .exchange()
                .expectStatus().isOk()
                .returnResult(Map.class).getResponseBody();
        return "Bearer " + token.get("accessToken");
    }

    @Test
    void aMemberSignsInBooksARoomAndReadsItBack() {
        String auth = signIn();

        var created = http.post().uri("/v1/bookings").header("Authorization", auth).body(BOOKING)
                .exchange()
                .expectStatus().isCreated()
                .returnResult(Map.class);

        http.get().uri(created.getResponseHeaders().getLocation()).header("Authorization", auth)
                .exchange()
                .expectStatus().isOk()
                .expectBody(Map.class).isEqualTo(created.getResponseBody());
    }

    @Test
    void letsExactlyOneOfTwoConcurrentRequestsWin() {
        String auth = signIn();

        List<CompletableFuture<Integer>> both = List.of(1, 2).stream()
                .map(i -> CompletableFuture.supplyAsync(() -> http.post().uri("/v1/bookings")
                        .header("Authorization", auth).body(BOOKING)
                        .exchange().returnResult().getStatus().value()))
                .toList();

        assertThat(both.stream().map(CompletableFuture::join).sorted()).containsExactly(201, 409);
    }
}

